	@Test
	void registeredExistingSnapshotIsUnavailableUntilDeferredConfiguration(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		seed(source, directory);
		int scans = source.scans.get();
		try (SketchBasedJoinEstimator estimator = estimator(source)) {
			estimator.registerPersistencePath(directory);
			assertFalse(estimator.isReadyNonBlocking(), "an uninspected persisted source cannot be current");
			assertFalse(estimator.forceFlush(), "deferred setup owns the first persisted load");
			QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
					QuadValueHash.hash(PREDICATE), 0L, 0L, estimator.quadSnapshotIdentity());
			assertFalse(estimator.synopsisService().probe(probe).usable());
			assertTrue(estimator.synopsisService().probePublishedCurrent(probe).isEmpty());
			assertEquals(scans, source.scans.get());
			estimator.configurePersistence(directory, true);
			assertTrue(estimator.isReadyNonBlocking());
			assertEquals(1.0d, predicateRows(estimator));
			assertEquals(scans, source.scans.get());
		}
	}

