	@Test
	void earlyCloseFencesAnInFlightMutationWithoutWaitingForItsGetter(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		seed(source, directory);
		Path snapshot = directory.resolve("synopsis-v8.bin");
		Path backup = directory.resolve("original-v8-backup.bin");
		Files.copy(snapshot, backup);
		Statement added = statement("second", 2);
		SketchBasedJoinEstimator estimator = estimator(source);
		estimator.registerPersistencePath(directory);
		estimator.setRebuildAllowedSupplier(() -> false);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Statement blocked = new AbstractStatement() {
			@Override
			public Resource getSubject() {
				entered.countDown();
				try {
					if (!release.await(10, TimeUnit.SECONDS)) {
						throw new IllegalStateException("getter not released");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(e);
				}
				return added.getSubject();
			}

			@Override
			public IRI getPredicate() {
				return added.getPredicate();
			}

			@Override
			public Value getObject() {
				return added.getObject();
			}

			@Override
			public Resource getContext() {
				return added.getContext();
			}
		};
		Thread worker = new Thread(() -> {
			try {
				estimator.addStatement(blocked);
			} catch (Throwable problem) {
				failure.set(problem);
			}
		}, "early-persistence-in-flight-add");
		worker.start();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			estimator.close();
			assertTrue(Files.isRegularFile(directory.resolve("synopsis-v8.rebuild")));
			assertEquals(-1L, Files.mismatch(snapshot, backup));
		} finally {
			source.rows.add(added);
			release.countDown();
			worker.join(TimeUnit.SECONDS.toMillis(10));
			estimator.close();
		}
		assertFalse(worker.isAlive());
		assertEquals(null, failure.get());
		try (SketchBasedJoinEstimator reopened = estimator(source)) {
			reopened.configurePersistence(directory, true);
			assertFalse(reopened.isReadyNonBlocking());
			assertTrue(reopened.forceFlush());
			assertEquals(2.0d, predicateRows(reopened));
		}
	}

