	private static void seed(Source source, Path directory) {
		try (SketchBasedJoinEstimator estimator = estimator(source)) {
			estimator.configurePersistence(directory, false);
			estimator.rebuild();
			estimator.persistIfDirty();
		}
	}

	private static SketchBasedJoinEstimator estimator(Source source) {
		return new SketchBasedJoinEstimator(source, SketchBasedJoinEstimator.Config.defaults()
				.withMemoryBudgetBytes(4L * 1024L * 1024L)
				.withColdSynopsisCapacity(64));
	}

	private static Statement statement(String name, int value) {
		return VF.createStatement(VF.createIRI("urn:early-persistence:" + name), PREDICATE, VF.createLiteral(value));
	}

	private static double predicateRows(SketchBasedJoinEstimator estimator) {
		QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
				QuadValueHash.hash(PREDICATE), 0L, 0L, estimator.quadSnapshotIdentity());
		var evidence = estimator.synopsisService().probe(probe);
		assertTrue(evidence.usable());
		return evidence.rows().estimate();
	}

	private static final class Source implements SketchStatementSource {
		private final List<Statement> rows = new CopyOnWriteArrayList<>();
		private final AtomicInteger scans = new AtomicInteger();

		@Override
		public CloseableIteratorIteration<Statement> getStatements(Resource s, IRI p, Value o, Resource... c) {
			scans.incrementAndGet();
			return new CloseableIteratorIteration<>(List.copyOf(rows).iterator());
		}
	}
